import {normalizeMotion,MOTION_KEY} from './motion-config.js';
const $=selector=>document.querySelector(selector),preview=$('#preview');
let defaults,config,saved,ready=false;
const status=message=>$('#status').textContent=message;
const selected=()=>config.pages.find(p=>p.number===Number($('#page').value));
function send(action='apply'){if(!ready)return;preview.contentWindow.postMessage({type:'portfolio-motion',action,config,page:Number($('#page').value),progress:Number($('#progress').value)/100},location.origin);}
function changed(){send('apply');status('已实时预览 · 尚未保存');}
function control(title,value,min,max,step,update){const box=document.createElement('div');box.className='control';const top=document.createElement('div');top.className='control-top';const label=document.createElement('label');label.textContent=title;const slider=document.createElement('input');slider.type='range';const number=document.createElement('input');number.type='number';const id='motion-'+crypto.randomUUID();slider.id=id;label.htmlFor=id;number.setAttribute('aria-label',title+'数值');for(const input of [slider,number]){Object.assign(input,{min,max,step,value});input.addEventListener('input',()=>{const raw=input.valueAsNumber;if(!Number.isFinite(raw))return;const v=Math.max(min,Math.min(max,raw));slider.value=number.value=String(v);update(v);changed();});}top.append(label,number);box.append(top,slider);return box;}
function render(){const p=selected();$('#page-title').textContent=`${p.number.toString().padStart(2,'0')} / ${p.label}`;$('#page-controls').replaceChildren(...[['翻页强度','turn',0,2,.01],['鼠标跟随','pointer',0,3,.05],['自动轻晃','ambient',0,1,.01]].map(([label,key,min,max,step])=>control(label,p[key],min,max,step,v=>p[key]=v)));$('#groups').replaceChildren(...p.groups.map(g=>{const box=document.createElement('div');box.className='group';const title=document.createElement('div');title.className='group-title';const image=document.createElement(g.src?'img':'span');image.className='thumb'+(g.src?'':' text-thumb');if(g.src){image.src=g.src;image.alt='';}else image.textContent='Aa';const name=document.createElement('span');name.textContent=g.label;title.append(image,name);box.append(title,control(g.label+' · 水平幅度',g.x,-3,3,.05,v=>g.x=v),control(g.label+' · 垂直幅度',g.y,-3,3,.05,v=>g.y=v));return box;}));}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==preview.contentWindow)return;if(event.data?.type==='portfolio-motion-ready'){defaults=event.data.defaults;config=event.data.config;saved=structuredClone(config);ready=true;$('#page').replaceChildren(...config.pages.map(p=>new Option(`${p.number.toString().padStart(2,'0')} / ${p.label}`,p.number)));render();$('#replay').disabled=false;status('预览已就绪。调整滑杆，试翻这一页。');}else if(event.data?.type==='portfolio-motion-error')status(event.data.message);});
$('#page').onchange=()=>{$('#progress').value=0;$('#progress-value').textContent='0%';render();send('show');};
$('#progress').oninput=()=>{$('#progress-value').textContent=$('#progress').value+'%';send('scrub');};
$('#replay').onclick=()=>{$('#progress').value=0;$('#progress-value').textContent='0%';send('replay');};
$('#settle').onclick=()=>{$('#progress').value=0;$('#progress-value').textContent='0%';send('scrub');};
$('#save').onclick=()=>{if(!ready)return;try{localStorage.setItem(MOTION_KEY,JSON.stringify(config));saved=structuredClone(config);status('已保存到本机网站。已打开的作品集刷新后也会采用这套动效。');}catch{status('保存失败，请先导出 JSON 备份。');}};
$('#restore').onclick=()=>{if(!ready)return;config=structuredClone(saved);render();send();status('已撤销未保存的调整。');};
$('#reset-page').onclick=()=>{if(!ready)return;const index=Number($('#page').value)-1;config.pages[index]=structuredClone(defaults.pages[index]);render();changed();};
$('#export').onclick=()=>{if(!ready)return;const url=URL.createObjectURL(new Blob([JSON.stringify(config,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='portfolio-motion.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('已导出当前配置。');};
$('#import-button').onclick=()=>$('#import').click();$('#import').onchange=async event=>{const file=event.target.files[0];if(!file||!ready)return;try{config=normalizeMotion(JSON.parse(await file.text()),defaults);render();send();status('已导入并预览，点击保存后应用到本机网站。');}catch(error){status('导入失败：'+error.message);}finally{event.target.value='';}};
